**Problem 4:**

Write a Python program that simulates a simple banking system. The program should allow users to create accounts, deposit money, withdraw money, and check their account balances.

**Complete Code:**
```python
class BankAccount:
    def __init__(self, account_number, initial_balance):
        self.account_number = account_number
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposited ${amount:.2f}. New balance: ${self.balance:.2f}")
        else:
            print("Invalid deposit amount.")

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            print(f"Withdrew ${amount:.2f}. New balance: ${self.balance:.2f}")
        elif amount <= 0:
            print("Invalid withdrawal amount.")
        else:
            print("Insufficient funds.")

    def check_balance(self):
        print(f"Current balance: ${self.balance:.2f}")


class BankingSystem:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_number, initial_balance):
        if account_number not in self.accounts:
            self.accounts[account_number] = BankAccount(account_number, initial_balance)
            print(f"Account created with number {account_number}.")
        else:
            print("Account number already exists.")

    def display_accounts(self):
        print("Current accounts:")
        for account_number, account in self.accounts.items():
            print(f"{account_number}: ${account.balance:.2f}")

    def run(self):
        while True:
            print("\n1. Create account")
            print("2. Deposit money")
            print("3. Withdraw money")
            print("4. Check balance")
            print("5. Exit")
            choice = input("Choose an option: ")
            if choice == "1":
                account_number = input("Enter account number: ")
                initial_balance = float(input("Enter initial balance: $"))
                self.create_account(account_number, initial_balance)
            elif choice == "2":
                account_number = input("Enter account number: ")
                amount = float(input("Enter deposit amount: $"))
                if account_number in self.accounts:
                    self.accounts[account_number].deposit(amount)
                else:
                    print("Account not found.")
            elif choice == "3":
                account_number = input("Enter account number: ")
                amount = float(input("Enter withdrawal amount: $"))
                if account_number in self.accounts:
                    self.accounts[account_number].withdraw(amount)
                else:
                    print("Account not found.")
            elif choice == "4":
                account_number = input("Enter account number: ")
                if account_number in self.accounts:
                    self.accounts[account_number].check_balance()
                else:
                    print("Account not found.")
            elif choice == "5":
                break
            else:
                print("Invalid option.")


if __name__ == "__main__":
    banking_system = BankingSystem()
    banking_system.run()
```
